import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"87. Using C with Other Languages (FFI)","description":"The Little Book of C — 87. Using C with Other Languages (FFI)","frontmatter":{"title":"87. Using C with Other Languages (FFI)","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Portable and Modern C"],"description":"The Little Book of C — 87. Using C with Other Languages (FFI)","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":87,"sidebarWeight":87,"lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI)","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI)"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI).md","filePath":"posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI).md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/09-Portable and Modern C/087-Using C with Other Languages (FFI).md"};function p(o,a,l,c,r,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/087-Using C with Other Languages (FFI))</p><p>C is often called the universal assembly language, nearly every modern language can call into it. This is made possible through the Foreign Function Interface (FFI), which defines how different languages talk to C code.</p><p>In this section, you’ll learn how to expose your C functions to Python, Rust, and Go, and how to call functions from those languages inside C.</p><h4 id="step-1-what-is-an-ffi" tabindex="-1">Step 1. What Is an FFI? <a class="header-anchor" href="#step-1-what-is-an-ffi" aria-label="Permalink to &quot;Step 1. What Is an FFI?&quot;">​</a></h4><p>An FFI (Foreign Function Interface) is a bridge that lets programs written in one language use code written in another.</p><p>Why FFI matters:</p><ul><li>Reuse fast, low-level C libraries (e.g., OpenSSL, SQLite).</li><li>Integrate C modules into higher-level languages like Python or Go.</li><li>Extend existing programs without rewriting everything.</li><li>Combine system-level control with productivity.</li></ul><h4 id="step-2-the-foundation-c-abi" tabindex="-1">Step 2. The Foundation: C ABI <a class="header-anchor" href="#step-2-the-foundation-c-abi" aria-label="Permalink to &quot;Step 2. The Foundation: C ABI&quot;">​</a></h4><p>The ABI (Application Binary Interface) defines how function calls, parameters, and data structures are represented in memory. The FFI works because C has a stable and simple ABI.</p><p>Rules include:</p><ul><li>How arguments are passed (registers or stack).</li><li>How return values are handled.</li><li>How data types are aligned in memory.</li></ul><p>That’s why almost every language provides a way to “speak” the C ABI.</p><h4 id="step-3-exposing-c-functions-to-other-languages" tabindex="-1">Step 3. Exposing C Functions to Other Languages <a class="header-anchor" href="#step-3-exposing-c-functions-to-other-languages" aria-label="Permalink to &quot;Step 3. Exposing C Functions to Other Languages&quot;">​</a></h4><p>You can make your C functions callable by other languages by marking them with<code>extern &quot;C&quot;</code>(if compiling as C++) or just regular C functions otherwise.</p><p>Tiny Code: Shared C Library</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file: mathlib.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int multiply(int a, int b) {</span></span>
<span class="line"><span>    return a * b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile it into a shared library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -fPIC -o libmathlib.so mathlib.c</span></span></code></pre></div><p>This creates a<code>.so</code>(Linux) or<code>.dll</code>(Windows) or<code>.dylib</code>(macOS) file you can load in other languages.</p><h4 id="step-4-using-c-in-python-ctypes" tabindex="-1">Step 4. Using C in Python (ctypes) <a class="header-anchor" href="#step-4-using-c-in-python-ctypes" aria-label="Permalink to &quot;Step 4. Using C in Python (ctypes)&quot;">​</a></h4><p>Python can call C functions directly using the<code>ctypes</code> module.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import ctypes</span></span>
<span class="line"><span>lib = ctypes.CDLL(&quot;./libmathlib.so&quot;)</span></span>
<span class="line"><span>print(lib.add(2, 3))</span></span>
<span class="line"><span>print(lib.multiply(4, 5))</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5</span></span>
<span class="line"><span>20</span></span></code></pre></div><p>Python automatically converts standard types (<code>int</code>,<code>float</code>,<code>char *</code>) to C equivalents.</p><p>For more complex types, you can define<code>ctypes.Structure</code> classes matching your C structs.</p><h4 id="step-5-using-c-in-rust" tabindex="-1">Step 5. Using C in Rust <a class="header-anchor" href="#step-5-using-c-in-rust" aria-label="Permalink to &quot;Step 5. Using C in Rust&quot;">​</a></h4><p>Rust has a built-in<code>extern &quot;C&quot;</code> block for FFI.</p><p>Rust Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#[link(name = &quot;mathlib&quot;)]</span></span>
<span class="line"><span>extern &quot;C&quot; {</span></span>
<span class="line"><span>    fn add(a: i32, b: i32) -&gt; i32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>fn main() {</span></span>
<span class="line"><span>    unsafe {</span></span>
<span class="line"><span>        println!(&quot;{}&quot;, add(2, 3));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rustc main.rs -L .</span></span></code></pre></div><p>Rust enforces<code>unsafe</code> because it can’t verify what happens inside the C function.</p><h4 id="step-6-using-c-in-go" tabindex="-1">Step 6. Using C in Go <a class="header-anchor" href="#step-6-using-c-in-go" aria-label="Permalink to &quot;Step 6. Using C in Go&quot;">​</a></h4><p>Go uses the<code>import &quot;C&quot;</code> directive for seamless C integration.</p><p>Go Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span>#include &quot;mathlib.c&quot;</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span>import &quot;C&quot;</span></span>
<span class="line"><span>import &quot;fmt&quot;</span></span>
<span class="line"><span>func main() {</span></span>
<span class="line"><span>    fmt.Println(C.add(2, 3))</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>go run main.go</span></span></code></pre></div><p>Go will compile your C code behind the scenes and link it automatically.</p><h4 id="step-7-calling-foreign-code-from-c" tabindex="-1">Step 7. Calling Foreign Code from C <a class="header-anchor" href="#step-7-calling-foreign-code-from-c" aria-label="Permalink to &quot;Step 7. Calling Foreign Code from C&quot;">​</a></h4><p>You can also go the other way, call functions from another language inside C.</p><p>Example: C calling Python</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;Python.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Py_Initialize();</span></span>
<span class="line"><span>    PyRun_SimpleString(&quot;print(&#39;Hello from Python in C!&#39;)&quot;);</span></span>
<span class="line"><span>    Py_Finalize();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -o main $(python3-config --cflags --ldflags)</span></span></code></pre></div><p>This embeds a Python interpreter in your C program, powerful for scripting or AI integration.</p><h4 id="step-8-data-structures-across-languages" tabindex="-1">Step 8. Data Structures Across Languages <a class="header-anchor" href="#step-8-data-structures-across-languages" aria-label="Permalink to &quot;Step 8. Data Structures Across Languages&quot;">​</a></h4><p>FFI works best with simple, C-compatible types:</p><ul><li><code>int</code>,<code>double</code>,<code>char *</code>, and flat structs. Avoid C++ classes, pointers to complex structs, or variable-length arrays, they often don’t translate cleanly.</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    int id;</span></span>
<span class="line"><span>    double score;</span></span>
<span class="line"><span>} Record;</span></span></code></pre></div><p>You can use this struct easily from Python (<code>ctypes.Structure</code>) or Rust (<code>#[repr(C)] struct</code>).</p><h4 id="step-9-memory-ownership-rules" tabindex="-1">Step 9. Memory Ownership Rules <a class="header-anchor" href="#step-9-memory-ownership-rules" aria-label="Permalink to &quot;Step 9. Memory Ownership Rules&quot;">​</a></h4><p>Always define who allocates and who frees memory.</p><p>If C allocates something:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char* greet(void) {</span></span>
<span class="line"><span>    char* s = malloc(32);</span></span>
<span class="line"><span>    sprintf(s, &quot;Hello from C!&quot;);</span></span>
<span class="line"><span>    return s;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Then the caller (e.g., Python) must call<code>free()</code> via FFI to avoid leaks. Never assume the garbage collector of another language will clean up C memory.</p><h4 id="step-10-tiny-code-c-shared-library-python" tabindex="-1">Step 10. Tiny Code: C Shared Library + Python <a class="header-anchor" href="#step-10-tiny-code-c-shared-library-python" aria-label="Permalink to &quot;Step 10. Tiny Code: C Shared Library + Python&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// greet.c</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>char* greet(const char* name) {</span></span>
<span class="line"><span>    static char buf[64];</span></span>
<span class="line"><span>    snprintf(buf, sizeof(buf), &quot;Hello, %s!&quot;, name);</span></span>
<span class="line"><span>    return buf;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -shared -fPIC -o libgreet.so greet.c</span></span></code></pre></div><p>Python:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import ctypes</span></span>
<span class="line"><span>lib = ctypes.CDLL(&quot;./libgreet.so&quot;)</span></span>
<span class="line"><span>lib.greet.restype = ctypes.c_char_p</span></span>
<span class="line"><span>print(lib.greet(b&quot;World&quot;))</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, World!</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>FFI turns C into the foundation of the software world, your C code can power systems written in any language. This is how databases, OS kernels, and AI frameworks expose APIs across ecosystems. Understanding FFI means you can build language bridges, not just programs.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a simple C library (math, strings, or sorting).</li><li>Load it in Python using<code>ctypes</code> and call its functions.</li><li>Reuse the same library from Rust using<code>extern &quot;C&quot;</code>.</li><li>Embed Python in C for a scripting layer.</li><li>Think about which side should own and free memory.</li></ol><p>Next, you’ll explore safer alternatives and modern C features, bounds checking, static assertions, and ways to make C code more reliable.</p>`,71)])])}const g=s(i,[["render",p]]);export{u as __pageData,g as default};
